int main(int argc,char**argv){Json output=Json::array();for(const auto&entry:std::filesystem::directory_iterator(argv[1])){auto file=entry.path()/"baselines/wang2023/result.json";if(!std::filesystem::exists(file))continue;Json r;std::ifstream(file)>>r;std::string level=r["case"]["level"];Json scene;std::ifstream(std::filesystem::path(argv[2])/"assets"/level/"scene.json")>>scene;Json record={{"level",level},{"failure",r["failure"]}};Json requests=Json::array();for(auto&q:r["requests"]){int gate=q["gate"].get<int>()-1;auto w=load_window(scene["windows"][gate]);Vector n=load_vector(r["reference_seed"]["normals"][gate]);auto h=load_state(q["head_state"]),t=load_state(q["tail_state"]);Json candidates=Json::array();int k=0;for(auto&c:q["candidates"]){Trajectory traj;traj.start=q["race_time_s"];for(auto&d:c["durations"])for(int i=0;i<4;++i)traj.durations.push_back(d.get<double>()/4.);for(auto&v:c["coefficients"]){Curve co;for(int p=0;p<8;++p)for(int a=0;a<3;++a)co(p,a)=v[p][a];traj.coefficients.push_back(co);}auto event=w.waypoint?Json{{"passed",true}}:crossing_event(traj,w,n,r["reference_seed"]["body_exit_depths"][gate]);candidates.push_back({{"seed",k++},{"eligible",c["stats"]["eligible"]},{"event",event},{"objective",c["stats"]["objective_scaled"]},{"T",traj.end()-traj.start}});}requests.push_back({{"gate",gate+1},{"selected",q["selected_seed"]},{"head_side",(h.col(0)-w.center).dot(n)},{"tail_side",(t.col(0)-w.center).dot(n)},{"tail_normal_velocity",t.col(1).dot(n)},{"candidates",candidates}});}record["requests"]=requests;output.push_back(record);}std::ofstream(argv[3])<<output.dump(2)<<'\n';}
